package com.gielinorgoals;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.SoundEffectID;

/**
 * Ett fåtal av spelets egna ljudeffekter att välja mellan när ett mål klaras.
 * Konstantnamnen sparas i config och får inte bytas.
 */
@RequiredArgsConstructor
public enum CompletionSound
{
	TROPHY_DING("Trophy ding", SoundEffectID.LEAGUE_TROPHY_DING),
	FANFARE("Fanfare", SoundEffectID.FANFARE),
	RELIC_UNLOCK("Relic unlock", SoundEffectID.RELIC_UNLOCK_HIGH_SOUND_1),
	TWINKLE("Twinkle", SoundEffectID.TRAILBLAZER_UNLOCK_TWUNKLES),
	CRYSTAL_CHIME("Crystal chime", SoundEffectID.ALTAR_CRYSTAL_CHIME_1);

	private final String label;
	@Getter
	private final int soundId;

	@Override
	public String toString()
	{
		return label;
	}
}

