package com.gielinorgoals.ui;

import java.awt.Color;

/**
 * Färgskalan för progress, delad mellan overlayen och panelens räknarmål:
 * vitt, sedan gult från 40 % och grönt från 75 %.
 */
final class ProgressColors
{
	private ProgressColors()
	{
	}

	static Color forFraction(double fraction)
	{
		if (fraction >= 0.75)
		{
			return Color.GREEN;
		}
		if (fraction >= 0.4)
		{
			return Color.YELLOW;
		}
		return Color.WHITE;
	}
}

