package com.gielinorgoals;

import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.SkillRequirement;
import com.gielinorgoals.tracking.InitialSync;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class GoalManagerTest
{
	private static final String PROFILE = "profile";

	private long now = 1_000_000L;
	private final Map<String, String> stored = new HashMap<>();
	private final List<List<Goal>> announced = new ArrayList<>();
	private InitialSync initialSync;
	private GoalManager manager;

	@Before
	public void setUp()
	{
		initialSync = new InitialSync(() -> now);
		manager = new GoalManager(new GoalManager.Storage()
		{
			@Override
			public String get(String profileKey, String key)
			{
				return stored.get(profileKey + "." + key);
			}

			@Override
			public void set(String profileKey, String key, String value)
			{
				stored.put(profileKey + "." + key, value);
			}
		}, new Gson(), initialSync);
		manager.setCompletionListener(announced::add);
		manager.loadProfile(PROFILE);
	}

	@Test
	public void goalMetInFirstSyncAfterLoginGetsApproxDate()
	{
		Goal goal = addCookingGoal();

		initialSync.start();
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		assertTrue(goal.isCompleted());
		assertTrue(goal.isCompletedAtApprox());
	}

	@Test
	public void goalMetAfterFirstSyncGetsExactDate()
	{
		Goal goal = addCookingGoal();
		manager.updateGameData(PROFILE, cookingXp(0));

		initialSync.start();
		now += InitialSync.WINDOW_MS;
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		assertTrue(goal.isCompleted());
		assertFalse(goal.isCompletedAtApprox());
		assertEquals(1, announced.size());
	}

	@Test
	public void goalAlreadyMetWhenAddedGetsApproxDate()
	{
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		Goal goal = addCookingGoal();

		assertTrue(goal.isCompleted());
		assertTrue(goal.isCompletedAtApprox());
		assertTrue(announced.isEmpty());
	}

	@Test
	public void goalMetWhileOfflineIsApproxAfterProfileLoad()
	{
		addCookingGoal();
		manager.updateGameData(PROFILE, cookingXp(1));
		manager.unload();

		// Samma profil laddas igen när datan redan visar att målet är nått.
		manager.updateGameData(PROFILE, cookingXp(1_000_000));
		manager.loadProfile(PROFILE);

		Goal reloaded = manager.getTree().getRoots().get(0);
		assertTrue(reloaded.isCompleted());
		assertTrue(reloaded.isCompletedAtApprox());
	}

	@Test
	public void manualTickIsExactAndUntickResetsDate()
	{
		manager.addGoal(null, "Fire cape", null, null);
		Goal goal = manager.getTree().getRoots().get(0);

		manager.setCompleted(goal.getId(), true);
		assertFalse(goal.isCompletedAtApprox());
		assertNotNull(goal.getCompletedAt());

		goal.setCompletedAtApprox(true);
		manager.setCompleted(goal.getId(), false);
		assertNull(goal.getCompletedAt());
		assertFalse(goal.isCompletedAtApprox());
	}

	@Test
	public void newGoalsGetCreatedAtAndSurviveReload()
	{
		manager.addGoal(null, "Fire cape", null, null);
		Long createdAt = manager.getTree().getRoots().get(0).getCreatedAt();

		manager.loadProfile(PROFILE);

		assertEquals(createdAt, manager.getTree().getRoots().get(0).getCreatedAt());
	}

	@Test
	public void revealExpandsCollapsedAncestors()
	{
		manager.addGoal(null, "Parent", null, null);
		Goal parent = manager.getTree().getRoots().get(0);
		manager.addGoal(parent.getId(), "Child", null, null);
		Goal child = manager.getTree().getChildren(parent).get(0);
		manager.toggleExpanded(parent.getId());
		assertFalse(parent.isExpanded());

		assertTrue(manager.reveal(child.getId()));

		assertTrue(parent.isExpanded());
		assertFalse(manager.reveal("missing"));
	}

	private Goal addCookingGoal()
	{
		manager.addGoal(null, "", null, SkillRequirement.level(Skill.COOKING, 70));
		return manager.getTree().getRoots().get(manager.getTree().getRoots().size() - 1);
	}

	private static GameData cookingXp(long xp)
	{
		return skill -> skill == Skill.COOKING ? xp : 0;
	}

	@Test
	public void showAsCounterCollapsesAndIsSaved()
	{
		manager.addGoal(null, "Quest cape", null, null);
		Goal cape = manager.getTree().getRoots().get(0);
		assertTrue(cape.isExpanded());

		manager.setAggregate(cape.getId(), true);

		assertTrue(cape.isAggregate());
		assertFalse(cape.isExpanded());
		manager.loadProfile(PROFILE);
		assertTrue(manager.getTree().getRoots().get(0).isAggregate());
	}

	@Test
	public void tickingLastSubGoalCompletesCounterWithPopupAndExactDate()
	{
		manager.addGoal(null, "Quest cape", null, null, true);
		Goal cape = manager.getTree().getRoots().get(0);
		manager.addGoal(cape.getId(), "Quest 1", null, null);
		manager.addGoal(cape.getId(), "Quest 2", null, null);
		List<Goal> quests = manager.getTree().getChildren(cape);

		manager.setCompleted(quests.get(0).getId(), true);
		assertFalse(cape.isCompleted());
		assertEquals("1/2", manager.getProgress(cape.getId()).getLabel());

		// Utan speldata, eftersom räknaren bara beror på delmålen.
		manager.setCompleted(quests.get(1).getId(), true);

		assertTrue(cape.isCompleted());
		assertFalse(cape.isCompletedAtApprox());
		assertEquals(List.of(List.of(cape)), announced);
	}

	@Test
	public void linkAndUnlinkAreSavedAndCyclesRefused()
	{
		manager.addGoal(null, "Barrows gloves", null, null);
		manager.addGoal(null, "Quest cape", null, null);
		Goal gloves = manager.getTree().getRoots().get(0);
		Goal cape = manager.getTree().getRoots().get(1);
		manager.addGoal(gloves.getId(), "Recipe for Disaster", null, null);
		Goal rfd = manager.getTree().getChildren(gloves).get(0);

		manager.link(cape.getId(), rfd.getId());
		manager.link(rfd.getId(), gloves.getId());
		manager.loadProfile(PROFILE);

		assertEquals(2, manager.getTree().getParents(rfd.getId()).size());
		assertTrue(manager.getTree().getChildren(manager.getTree().find(rfd.getId())).isEmpty());

		manager.unlink(gloves.getId(), rfd.getId());
		manager.loadProfile(PROFILE);
		assertEquals(List.of(cape.getId()),
			List.of(manager.getTree().getParents(rfd.getId()).get(0).getId()));
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class AchievementRequirementsTest
{
	@Test
	public void questIsCompleteOnlyWhenFinished()
	{
		QuestRequirement requirement = new QuestRequirement(42, "Dragon Slayer I");

		assertEquals("Not started", requirement.progress(quest(42, QuestState.NOT_STARTED)).getLabel());
		GoalProgress inProgress = requirement.progress(quest(42, QuestState.IN_PROGRESS));
		assertFalse(inProgress.isComplete());
		assertEquals(0.5, inProgress.fraction(), 0.0);
		assertTrue(requirement.progress(quest(42, QuestState.FINISHED)).isComplete());
		assertNull(requirement.progress(GameData.EMPTY));
		assertEquals("Complete Dragon Slayer I", requirement.describe());
	}

	@Test
	public void regularDiaryTierIsCompleteAtOne()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.VARROCK, DiaryTier.HARD);
		assertEquals(VarbitID.VARROCK_DIARY_HARD_COMPLETE, requirement.varbit());

		assertFalse(requirement.progress(varbit(requirement.varbit(), 0)).isComplete());
		assertTrue(requirement.progress(varbit(requirement.varbit(), 1)).isComplete());
		assertEquals("Varrock Hard diary", requirement.describe());
	}

	@Test
	public void karamjaLowTiersNeedTwoButEliteNeedsOne()
	{
		DiaryRequirement easy = new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.EASY);
		assertEquals(VarbitID.ATJUN_EASY_DONE, easy.varbit());
		assertFalse(easy.progress(varbit(easy.varbit(), 1)).isComplete());
		assertTrue(easy.progress(varbit(easy.varbit(), 2)).isComplete());

		DiaryRequirement elite = new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.ELITE);
		assertEquals(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, elite.varbit());
		assertTrue(elite.progress(varbit(elite.varbit(), 1)).isComplete());
	}

	@Test
	public void diaryShowsTaskCountWhenKnown()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.VARROCK, DiaryTier.EASY);
		GameData data = varbits(Map.of(requirement.varbit(), 0, requirement.countVarbit(), 7));

		GoalProgress progress = requirement.progress(data);

		assertEquals("7/14 tasks", progress.getLabel());
		assertEquals(0.5, progress.fraction(), 0.0);
		assertFalse(progress.isComplete());
	}

	@Test
	public void completedDiaryShowsFullCount()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.ARDOUGNE, DiaryTier.ELITE);
		GoalProgress progress = requirement.progress(varbits(Map.of(requirement.varbit(), 1, requirement.countVarbit(), 3)));

		assertTrue(progress.isComplete());
		assertEquals("8/8 tasks", progress.getLabel());
	}

	@Test
	public void journalTitleMapsToArea()
	{
		assertEquals(DiaryArea.VARROCK, DiaryArea.fromJournalTitle("Varrock Area Tasks"));
		assertEquals(DiaryArea.KOUREND, DiaryArea.fromJournalTitle("<col=7f0000>Kourend & Kebos Tasks</col>"));
		assertEquals(DiaryArea.LUMBRIDGE, DiaryArea.fromJournalTitle("Lumbridge & Draynor Tasks"));
		assertNull(DiaryArea.fromJournalTitle("Cook's Assistant"));
	}

	@Test
	public void unreadDiaryVarbitGivesNoProgress()
	{
		assertNull(new DiaryRequirement(DiaryArea.DESERT, DiaryTier.EASY).progress(GameData.EMPTY));
	}

	@Test
	public void combatAchievementFollowsCompletionFlag()
	{
		CombatAchievementRequirement requirement = new CombatAchievementRequirement(17, "Noxious Foe", "Easy");

		assertFalse(requirement.progress(ca(17, false)).isComplete());
		assertTrue(requirement.progress(ca(17, true)).isComplete());
		assertNull(requirement.progress(GameData.EMPTY));
		assertEquals("CA (Easy): Noxious Foe", requirement.describe());
	}

	private static GameData quest(int id, QuestState state)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public QuestState getQuestState(int questId)
			{
				return questId == id ? state : null;
			}
		};
	}

	private static GameData varbit(int id, int value)
	{
		return varbits(Map.of(id, value));
	}

	private static GameData varbits(Map<Integer, Integer> values)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public int getVarbit(int varbitId)
			{
				return values.getOrDefault(varbitId, -1);
			}
		};
	}

	private static GameData ca(int id, boolean complete)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public Boolean isCombatAchievementComplete(int taskId)
			{
				return taskId == id ? complete : null;
			}
		};
	}
}

package com.gielinorgoals.model;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CompletedLogTest
{
	private static final ZoneId ZONE = ZoneId.of("Europe/Stockholm");

	@Test
	public void midnightSeparatesTodayAndYesterdayAcrossMonthEnd()
	{
		// Tisdag 1 december.
		long now = at(2026, 12, 1, 10, 0, 0);

		assertEquals("Today", group(at(2026, 12, 1, 0, 0, 30), now));
		assertEquals("Yesterday", group(at(2026, 11, 30, 23, 59, 30), now));
		// Söndag i förra veckan och förra månaden.
		assertEquals("November 2026", group(at(2026, 11, 29, 23, 59, 0), now));
	}

	@Test
	public void justAfterMidnightYesterdayIsTheDayBefore()
	{
		// Onsdag 4 november, tio sekunder efter midnatt.
		long now = at(2026, 11, 4, 0, 0, 10);

		assertEquals("Today", group(at(2026, 11, 4, 0, 0, 0), now));
		assertEquals("Yesterday", group(at(2026, 11, 3, 23, 59, 50), now));
		assertEquals("This week", group(at(2026, 11, 2, 12, 0, 0), now));
		// Söndagen före måndag hör till förra veckan men samma månad.
		assertEquals("This month", group(at(2026, 11, 1, 12, 0, 0), now));
		assertEquals("October 2026", group(at(2026, 10, 31, 23, 59, 59), now));
	}

	@Test
	public void weekStartingInPreviousMonthIsThisWeek()
	{
		// Torsdag 3 december; veckan började måndag 30 november.
		long now = at(2026, 12, 3, 12, 0, 0);

		assertEquals("This week", group(at(2026, 11, 30, 8, 0, 0), now));
		assertEquals("November 2026", group(at(2026, 11, 29, 8, 0, 0), now));
	}

	@Test
	public void futureDateCountsAsToday()
	{
		long now = at(2026, 12, 1, 10, 0, 0);
		assertEquals("Today", group(at(2026, 12, 2, 10, 0, 0), now));
	}

	@Test
	public void timeToCompleteCountsWholeDays()
	{
		long created = at(2026, 11, 1, 12, 0, 0);

		assertEquals("Took 3 days", CompletedLog.timeToComplete(goal(created, created + 3 * CompletedLog.DAY_MS + 5_000)));
		assertEquals("Took 1 day", CompletedLog.timeToComplete(goal(created, created + CompletedLog.DAY_MS)));
		assertEquals("Took under a day", CompletedLog.timeToComplete(goal(created, created + 2 * 60 * 60 * 1000)));
	}

	@Test
	public void timeToCompleteNeedsBothExactDates()
	{
		long created = at(2026, 11, 1, 12, 0, 0);

		Goal approx = goal(created, created + CompletedLog.DAY_MS);
		approx.markCompleted(true, created + CompletedLog.DAY_MS, true);
		assertNull(CompletedLog.timeToComplete(approx));

		Goal oldGoal = goal(created, created + CompletedLog.DAY_MS);
		oldGoal.setCreatedAt(null);
		assertNull(CompletedLog.timeToComplete(oldGoal));

		Goal open = new Goal("Open");
		assertNull(CompletedLog.timeToComplete(open));
	}

	@Test
	public void uncompletingResetsDateAndApproxFlag()
	{
		Goal goal = new Goal("A");
		goal.markCompleted(true, 1234L, true);
		assertTrue(goal.isCompletedAtApprox());

		goal.markCompleted(false, 5678L);

		assertFalse(goal.isCompleted());
		assertNull(goal.getCompletedAt());
		assertFalse(goal.isCompletedAtApprox());
	}

	@Test
	public void buildListsAllLevelsGroupedAndSorted()
	{
		long now = at(2026, 12, 3, 12, 0, 0);
		GoalTree tree = new GoalTree();
		Goal gloves = new Goal("Barrows gloves");
		Goal cooking = new Goal("");
		cooking.setRequirement(SkillRequirement.level(Skill.COOKING, 70));
		Goal open = new Goal("Not done");
		Goal undated = new Goal("Old goal");
		tree.add(null, gloves);
		tree.add(gloves.getId(), cooking);
		tree.add(gloves.getId(), open);
		tree.add(null, undated);

		gloves.markCompleted(true, at(2026, 10, 5, 12, 0, 0));
		cooking.markCompleted(true, at(2026, 12, 3, 9, 0, 0));
		undated.setCompleted(true);

		List<CompletedLog.Section> newest = CompletedLog.build(tree, CompletedLog.TypeFilter.ALL, false, true, now, ZONE);
		assertEquals(List.of("Today", "October 2026", "Unknown date"), headers(newest));
		CompletedLog.Entry first = newest.get(0).getEntries().get(0);
		assertEquals("70 Cooking", first.getGoal().getDisplayTitle());
		assertEquals("Barrows gloves", first.getParents());
		assertNull(newest.get(1).getEntries().get(0).getParents());

		List<CompletedLog.Section> oldest = CompletedLog.build(tree, CompletedLog.TypeFilter.ALL, false, false, now, ZONE);
		assertEquals(List.of("October 2026", "Today", "Unknown date"), headers(oldest));
	}

	@Test
	public void buildFiltersByTypeAndRootsOnly()
	{
		long now = at(2026, 12, 3, 12, 0, 0);
		GoalTree tree = new GoalTree();
		Goal gloves = new Goal("Barrows gloves");
		Goal cooking = new Goal("");
		cooking.setRequirement(SkillRequirement.level(Skill.COOKING, 70));
		tree.add(null, gloves);
		tree.add(gloves.getId(), cooking);
		gloves.markCompleted(true, now);
		cooking.markCompleted(true, now);

		assertEquals(List.of("70 Cooking"),
			titles(CompletedLog.build(tree, CompletedLog.TypeFilter.SKILL, false, true, now, ZONE)));
		assertEquals(List.of("Barrows gloves"),
			titles(CompletedLog.build(tree, CompletedLog.TypeFilter.MANUAL, false, true, now, ZONE)));
		assertEquals(List.of("Barrows gloves"),
			titles(CompletedLog.build(tree, CompletedLog.TypeFilter.ALL, true, true, now, ZONE)));
		assertTrue(CompletedLog.build(tree, CompletedLog.TypeFilter.QUEST, false, true, now, ZONE).isEmpty());
	}

	@Test
	public void statsCountAllCompletedGoals()
	{
		long now = at(2026, 12, 3, 12, 0, 0);
		GoalTree tree = new GoalTree();
		Goal exact = new Goal("Fire cape");
		exact.setCreatedAt(at(2026, 11, 29, 12, 0, 0));
		exact.markCompleted(true, at(2026, 12, 1, 12, 0, 0));
		Goal approx = new Goal("Old quest");
		approx.setCreatedAt(at(2026, 1, 1, 12, 0, 0));
		approx.markCompleted(true, at(2026, 12, 2, 12, 0, 0), true);
		Goal lastMonth = new Goal("Barrows gloves");
		lastMonth.setCreatedAt(at(2026, 11, 1, 12, 0, 0));
		lastMonth.markCompleted(true, at(2026, 11, 5, 12, 0, 0));
		Goal noCreatedAt = new Goal("Legacy");
		noCreatedAt.setCreatedAt(null);
		noCreatedAt.markCompleted(true, at(2026, 10, 1, 12, 0, 0));
		Goal undated = new Goal("Undated");
		undated.setCompleted(true);
		Goal open = new Goal("Open");
		for (Goal goal : List.of(exact, approx, lastMonth, noCreatedAt, undated, open))
		{
			tree.add(null, goal);
		}

		CompletedLog.Stats stats = CompletedLog.stats(tree, now, ZONE);

		assertEquals(5, stats.getTotal());
		assertEquals(2, stats.getThisMonth());
		assertEquals("Old quest", stats.getLatest().getTitle());
		// Bara exakta mål med createdAt: 2 dagar och 4 dagar.
		assertEquals(Long.valueOf(3 * CompletedLog.DAY_MS), stats.getAverageMs());
	}

	@Test
	public void statsWithoutDurationsHaveNoAverage()
	{
		GoalTree tree = new GoalTree();
		Goal approx = new Goal("Old quest");
		approx.markCompleted(true, 1000L, true);
		tree.add(null, approx);

		CompletedLog.Stats stats = CompletedLog.stats(tree, 2000L, ZONE);

		assertEquals(1, stats.getTotal());
		assertNull(stats.getAverageMs());
		assertEquals(0, CompletedLog.stats(new GoalTree(), 2000L, ZONE).getTotal());
	}

	@Test
	public void daysAgoCountsCalendarDays()
	{
		long now = at(2026, 12, 3, 0, 0, 10);

		assertEquals("today", CompletedLog.daysAgo(at(2026, 12, 3, 0, 0, 0), now, ZONE));
		assertEquals("yesterday", CompletedLog.daysAgo(at(2026, 12, 2, 23, 59, 59), now, ZONE));
		assertEquals("2 days ago", CompletedLog.daysAgo(at(2026, 12, 1, 0, 0, 0), now, ZONE));
	}

	@Test
	public void formatDurationPicksReadableUnit()
	{
		long hour = 60L * 60 * 1000;
		assertEquals("under an hour", CompletedLog.formatDuration(10 * 60 * 1000));
		assertEquals("1 hour", CompletedLog.formatDuration(hour));
		assertEquals("5 hours", CompletedLog.formatDuration(5 * hour + 59 * 60 * 1000));
		assertEquals("1 day", CompletedLog.formatDuration(CompletedLog.DAY_MS));
		assertEquals("1.5 days", CompletedLog.formatDuration(CompletedLog.DAY_MS * 3 / 2));
		assertEquals("3 days", CompletedLog.formatDuration(3 * CompletedLog.DAY_MS));
		assertEquals("12 days", CompletedLog.formatDuration(12 * CompletedLog.DAY_MS + 3 * hour));
	}

	@Test
	public void formatDateUsesShortMonth()
	{
		assertEquals("12 Nov 2026", CompletedLog.formatDate(at(2026, 11, 12, 23, 30, 0), ZONE));
	}

	private static Goal goal(long createdAt, long completedAt)
	{
		Goal goal = new Goal("Goal");
		goal.setCreatedAt(createdAt);
		goal.markCompleted(true, completedAt);
		return goal;
	}

	private static String group(long completedAt, long now)
	{
		return CompletedLog.groupFor(completedAt, now, ZONE);
	}

	private static long at(int year, int month, int day, int hour, int minute, int second)
	{
		return LocalDateTime.of(year, month, day, hour, minute, second).atZone(ZONE).toInstant().toEpochMilli();
	}

	private static List<String> headers(List<CompletedLog.Section> sections)
	{
		List<String> headers = new ArrayList<>();
		sections.forEach(section -> headers.add(section.getHeader()));
		return headers;
	}

	private static List<String> titles(List<CompletedLog.Section> sections)
	{
		List<String> titles = new ArrayList<>();
		sections.forEach(section -> section.getEntries().forEach(e -> titles.add(e.getGoal().getDisplayTitle())));
		return titles;
	}

	@Test
	public void sharedGoalListsAllParentsOnce()
	{
		long now = at(2026, 12, 3, 12, 0, 0);
		GoalTree tree = new GoalTree();
		Goal gloves = new Goal("Barrows gloves");
		Goal questCape = new Goal("Quest cape");
		Goal rfd = new Goal("Recipe for Disaster");
		tree.add(null, gloves);
		tree.add(null, questCape);
		tree.add(gloves.getId(), rfd);
		tree.link(questCape.getId(), rfd.getId());
		rfd.markCompleted(true, now);

		List<CompletedLog.Section> sections = CompletedLog.build(tree, CompletedLog.TypeFilter.ALL, false, true, now, ZONE);

		assertEquals(1, sections.get(0).getEntries().size());
		assertEquals("Barrows gloves, Quest cape", sections.get(0).getEntries().get(0).getParents());
		assertEquals(1, CompletedLog.stats(tree, now, ZONE).getTotal());
	}
}

package com.gielinorgoals.model;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class CompletionFilterTest
{
	private GoalTree tree;
	private Goal gloves;
	private Goal quest;
	private Goal subQuest;
	private Goal skill;
	private Goal other;

	// gloves -> quest -> subQuest, gloves -> skill; other är ett eget rotmål.
	@Before
	public void setUp()
	{
		tree = new GoalTree();
		gloves = new Goal("Barrows gloves");
		quest = new Goal("Recipe for Disaster");
		subQuest = new Goal("Desert Treasure");
		skill = new Goal("70 Cooking");
		other = new Goal("Fire cape");
		tree.add(null, gloves);
		tree.add(gloves.getId(), quest);
		tree.add(quest.getId(), subQuest);
		tree.add(gloves.getId(), skill);
		tree.add(null, other);
	}

	@Test
	public void isAncestorWorksAtAnyDepth()
	{
		assertTrue(tree.isAncestor(gloves.getId(), quest.getId()));
		assertTrue(tree.isAncestor(gloves.getId(), subQuest.getId()));
		assertFalse(tree.isAncestor(subQuest.getId(), gloves.getId()));
		assertFalse(tree.isAncestor(gloves.getId(), gloves.getId()));
		assertFalse(tree.isAncestor(other.getId(), skill.getId()));
	}

	@Test
	public void getParentsReturnsDirectParents()
	{
		assertEquals(List.of(gloves), tree.getParents(quest.getId()));
		assertEquals(List.of(quest), tree.getParents(subQuest.getId()));
		assertTrue(tree.getParents(gloves.getId()).isEmpty());
	}

	@Test
	public void goalAndChildrenInSameBatchShowOnlyTopGoal()
	{
		complete(gloves, quest, skill);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(gloves, quest, skill), false);

		assertEquals(1, entries.size());
		assertSame(gloves, entries.get(0).getGoal());
		assertEquals(2, entries.get(0).getHiddenDescendants());
		assertTrue(entries.get(0).isRoot());
	}

	@Test
	public void deepSubGoalIsHiddenEvenWhenMiddleGoalIsNotInBatch()
	{
		complete(gloves, subQuest);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(gloves, subQuest), false);

		assertEquals(1, entries.size());
		assertSame(gloves, entries.get(0).getGoal());
		assertEquals(1, entries.get(0).getHiddenDescendants());
	}

	@Test
	public void subGoalShowsProgressInOpenParent()
	{
		complete(skill);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(skill), false);

		assertEquals(1, entries.size());
		CompletionFilter.Entry entry = entries.get(0);
		assertFalse(entry.isRoot());
		assertSame(gloves, entry.getOpenParent());
		assertEquals(1, entry.getParentDone());
		assertEquals(2, entry.getParentTotal());
	}

	@Test
	public void unrelatedGoalsGetOwnEntries()
	{
		complete(skill, other);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(skill, other), false);

		assertEquals(2, entries.size());
		assertSame(skill, entries.get(0).getGoal());
		assertSame(other, entries.get(1).getGoal());
		assertNull(entries.get(1).getOpenParent());
	}

	@Test
	public void rootsOnlyDropsSubGoals()
	{
		complete(skill, other);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(skill, other), true);

		assertEquals(1, entries.size());
		assertSame(other, entries.get(0).getGoal());
	}

	@Test
	public void rootsOnlyKeepsRootWithItsSubGoalsCounted()
	{
		complete(gloves, quest, subQuest, skill);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree,
			List.of(gloves, quest, subQuest, skill), true);

		assertEquals(1, entries.size());
		assertSame(gloves, entries.get(0).getGoal());
		assertEquals(3, entries.get(0).getHiddenDescendants());
	}

	private static void complete(Goal... goals)
	{
		for (Goal goal : goals)
		{
			goal.markCompleted(true, 1L);
		}
	}

	@Test
	public void sharedGoalGivesOnePopupAndCountsInParent()
	{
		Goal questCape = new Goal("Quest cape");
		tree.add(null, questCape);
		tree.link(questCape.getId(), quest.getId());
		complete(quest);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(quest), false);

		assertEquals(1, entries.size());
		assertFalse(entries.get(0).isRoot());
		// Första oklara föräldern används för progressraden.
		assertSame(gloves, entries.get(0).getOpenParent());
		assertEquals(List.of(gloves, questCape), tree.getParents(quest.getId()));
	}

	@Test
	public void sharedSubGoalIsHiddenWhenEitherAncestorCompletes()
	{
		Goal questCape = new Goal("Quest cape");
		tree.add(null, questCape);
		tree.link(questCape.getId(), subQuest.getId());
		complete(questCape, subQuest);

		List<CompletionFilter.Entry> entries = CompletionFilter.filter(tree, List.of(questCape, subQuest), false);

		assertEquals(1, entries.size());
		assertSame(questCape, entries.get(0).getGoal());
		assertEquals(1, entries.get(0).getHiddenDescendants());
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

public class GoalEvaluatorTest
{
	private GoalTree tree;
	private Goal agility;
	private Goal manual;

	@Before
	public void setUp()
	{
		tree = new GoalTree();
		agility = new Goal("");
		agility.setRequirement(SkillRequirement.level(Skill.AGILITY, 50));
		manual = new Goal("Buy a house");
		tree.add(null, manual);
		tree.add(manual.getId(), agility);
	}

	@Test
	public void completesGoalWhenRequirementIsMet()
	{
		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, agilityXp(50), 1000L);

		assertTrue(agility.isCompleted());
		assertEquals(Long.valueOf(1000L), agility.getCompletedAt());
		assertEquals(1, result.getNewlyCompleted().size());
		assertEquals(agility, result.getNewlyCompleted().get(0));
	}

	@Test
	public void progressIsReportedOnlyForAutomaticGoals()
	{
		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, agilityXp(40), 0L);

		assertFalse(agility.isCompleted());
		assertTrue(result.getNewlyCompleted().isEmpty());
		assertEquals("40/50", result.getProgress().get(agility.getId()).getLabel());
		assertFalse(result.getProgress().containsKey(manual.getId()));
	}

	@Test
	public void completedGoalIsLatchedAndReportedOnce()
	{
		GoalEvaluator.evaluate(tree, agilityXp(50), 1000L);
		GoalEvaluator.Result second = GoalEvaluator.evaluate(tree, agilityXp(50), 2000L);

		assertTrue(second.getNewlyCompleted().isEmpty());
		assertEquals(Long.valueOf(1000L), agility.getCompletedAt());
	}

	@Test
	public void latchSurvivesDataThatNoLongerMeetsRequirement()
	{
		GoalEvaluator.evaluate(tree, agilityXp(50), 1000L);
		GoalEvaluator.evaluate(tree, agilityXp(1), 2000L);

		assertTrue(agility.isCompleted());
	}

	@Test
	public void unknownDataChangesNothing()
	{
		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, GameData.EMPTY, 0L);

		assertFalse(agility.isCompleted());
		assertTrue(result.getProgress().isEmpty());
	}

	@Test
	public void manualGoalsAreNeverTouched()
	{
		GoalEvaluator.evaluate(tree, agilityXp(99), 0L);
		assertFalse(manual.isCompleted());
	}

	private static GameData agilityXp(int level)
	{
		return SkillRequirementTest.xp(Skill.AGILITY, Experience.getXpForLevel(level));
	}

	@Test
	public void sharedGoalIsEvaluatedAndReportedOnce()
	{
		Goal other = new Goal("Quest cape");
		tree.add(null, other);
		tree.link(other.getId(), agility.getId());

		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, agilityXp(50), 1000L);

		assertEquals(1, result.getNewlyCompleted().size());
		assertEquals(agility, result.getNewlyCompleted().get(0));
	}

	@Test
	public void aggregateCountsDirectChildrenAndCompletesWhenAllDone()
	{
		Goal cape = new Goal("Quest cape");
		cape.setAggregate(true);
		Goal q1 = new Goal("Quest 1");
		Goal q2 = new Goal("Quest 2");
		Goal deep = new Goal("Step of quest 2");
		tree.add(null, cape);
		tree.add(cape.getId(), q1);
		tree.add(cape.getId(), q2);
		tree.add(q2.getId(), deep);
		q1.markCompleted(true, 1L);

		GoalEvaluator.Result first = GoalEvaluator.evaluate(tree, GameData.EMPTY, 1000L);
		GoalProgress counter = first.getProgress().get(cape.getId());
		assertEquals("1/2", counter.getLabel());
		assertFalse(counter.isComplete());
		assertFalse(cape.isCompleted());

		// Bara direkta delmål räknas; det djupa delmålet påverkar inte räknaren.
		q2.markCompleted(true, 2L);
		GoalEvaluator.Result second = GoalEvaluator.evaluate(tree, GameData.EMPTY, 2000L);
		assertTrue(cape.isCompleted());
		assertEquals(Long.valueOf(2000L), cape.getCompletedAt());
		assertEquals(java.util.List.of(cape), second.getNewlyCompleted());
		assertEquals("2/2", second.getProgress().get(cape.getId()).getLabel());
	}

	@Test
	public void nestedAggregatesCompleteInOneEvaluationEvenWhenShared()
	{
		// A har X och Y, och X är även delmål till Y. Alla tre är räknarmål.
		Goal a = new Goal("A");
		Goal x = new Goal("X");
		Goal y = new Goal("Y");
		Goal leaf = new Goal("Leaf");
		for (Goal goal : java.util.List.of(a, x, y))
		{
			goal.setAggregate(true);
		}
		tree.add(null, a);
		tree.add(a.getId(), x);
		tree.add(a.getId(), y);
		tree.link(y.getId(), x.getId());
		tree.add(x.getId(), leaf);
		leaf.markCompleted(true, 1L);

		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, GameData.EMPTY, 1000L);

		assertTrue(x.isCompleted());
		assertTrue(y.isCompleted());
		assertTrue(a.isCompleted());
		assertEquals(3, result.getNewlyCompleted().size());
	}

	@Test
	public void aggregateWithRequirementIsNotCompletedByChildren()
	{
		manual.setAggregate(true);
		manual.setRequirement(SkillRequirement.level(Skill.MINING, 99));
		agility.markCompleted(true, 1L);

		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, SkillRequirementTest.xp(Skill.MINING, 0), 1000L);

		// Alla delmål är klara, men med eget krav styr kravet när målet är klart,
		// och kravets progress visas (level 1 av 99).
		assertFalse(manual.isCompleted());
		assertEquals("1/99", result.getProgress().get(manual.getId()).getLabel());
	}

	@Test
	public void emptyAggregateIsNeverCompleted()
	{
		Goal empty = new Goal("Empty");
		empty.setAggregate(true);
		tree.add(null, empty);

		GoalEvaluator.evaluate(tree, GameData.EMPTY, 1000L);

		assertFalse(empty.isCompleted());
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class GoalTreeTest
{
	private GoalTree tree;
	private Goal a;
	private Goal b;
	private Goal c;

	@Before
	public void setUp()
	{
		tree = new GoalTree();
		a = new Goal("A");
		b = new Goal("B");
		c = new Goal("C");
		tree.add(null, a);
		tree.add(null, b);
		tree.add(null, c);
	}

	@Test
	public void addAppendsToRootInOrder()
	{
		assertEquals(List.of("A", "B", "C"), titles(tree.getRoots()));
	}

	@Test
	public void addAsChildExpandsParent()
	{
		a.setExpanded(false);
		Goal child = new Goal("A1");

		assertTrue(tree.add(a.getId(), child));
		assertEquals(List.of("A1"), titles(tree.getChildren(a)));
		assertTrue(a.isExpanded());
		assertEquals(child, tree.find(child.getId()));
	}

	@Test
	public void addToMissingParentFails()
	{
		assertFalse(tree.add("missing", new Goal("X")));
		assertEquals(3, tree.size());
	}

	@Test
	public void removeDeletesGoalWithChildren()
	{
		Goal child = new Goal("B1");
		tree.add(b.getId(), child);

		assertTrue(tree.remove(b.getId()));
		assertEquals(List.of("A", "C"), titles(tree.getRoots()));
		assertNull(tree.find(child.getId()));
	}

	@Test
	public void moveUpAndDownSwapWithinSiblings()
	{
		assertTrue(tree.moveUp(null, c.getId()));
		assertEquals(List.of("A", "C", "B"), titles(tree.getRoots()));

		assertTrue(tree.moveDown(null, a.getId()));
		assertEquals(List.of("C", "A", "B"), titles(tree.getRoots()));
	}

	@Test
	public void moveBeyondEdgesFails()
	{
		assertFalse(tree.moveUp(null, a.getId()));
		assertFalse(tree.moveDown(null, c.getId()));
		assertFalse(tree.canMoveUp(null, a.getId()));
		assertFalse(tree.canMoveDown(null, c.getId()));
	}

	@Test
	public void indentMakesGoalLastChildOfPreviousSibling()
	{
		Goal existing = new Goal("A1");
		tree.add(a.getId(), existing);

		assertTrue(tree.indent(null, b.getId()));
		assertEquals(List.of("A", "C"), titles(tree.getRoots()));
		assertEquals(List.of("A1", "B"), titles(tree.getChildren(a)));
	}

	@Test
	public void indentFirstSiblingFails()
	{
		assertFalse(tree.canIndent(null, a.getId()));
		assertFalse(tree.indent(null, a.getId()));
	}

	@Test
	public void outdentPlacesGoalDirectlyAfterParent()
	{
		Goal child = new Goal("A1");
		tree.add(a.getId(), child);

		assertTrue(tree.outdent(null, a.getId(), child.getId()));
		assertEquals(List.of("A", "A1", "B", "C"), titles(tree.getRoots()));
		assertTrue(tree.getChildren(a).isEmpty());
	}

	@Test
	public void outdentRootFails()
	{
		assertFalse(tree.canOutdent(null, null, a.getId()));
		assertFalse(tree.outdent(null, b.getId(), a.getId()));
	}

	@Test
	public void setCompletedStoresTimestamp()
	{
		assertTrue(tree.setCompleted(a.getId(), true, 1234L));
		assertTrue(a.isCompleted());
		assertEquals(Long.valueOf(1234L), a.getCompletedAt());

		tree.setCompleted(a.getId(), false, 5678L);
		assertFalse(a.isCompleted());
		assertNull(a.getCompletedAt());
	}

	@Test
	public void forEachVisitsParentsBeforeChildren()
	{
		tree.add(a.getId(), new Goal("A1"));
		List<String> visited = new ArrayList<>();
		tree.forEach(goal -> visited.add(goal.getTitle()));

		assertEquals(List.of("A", "A1", "B", "C"), visited);
	}

	@Test
	public void linkSharesGoalBetweenParentsAndStoresItOnce()
	{
		Goal rfd = new Goal("Recipe for Disaster");
		tree.add(a.getId(), rfd);

		assertTrue(tree.link(b.getId(), rfd.getId()));

		assertEquals(List.of(a, b), tree.getParents(rfd.getId()));
		assertEquals(4, tree.size());
		assertTrue(tree.isAncestor(b.getId(), rfd.getId()));
		// Redan kopplad.
		assertFalse(tree.link(b.getId(), rfd.getId()));
	}

	@Test
	public void linkingRootMakesItSubGoal()
	{
		assertTrue(tree.link(a.getId(), c.getId()));

		assertEquals(List.of("A", "B"), titles(tree.getRoots()));
		assertEquals(List.of("C"), titles(tree.getChildren(a)));
	}

	@Test
	public void linkRefusesCycles()
	{
		Goal child = new Goal("A1");
		Goal grandchild = new Goal("A1a");
		tree.add(a.getId(), child);
		tree.add(child.getId(), grandchild);

		// A är förfader till A1a, så A1a -> A skulle bli en cykel.
		assertFalse(tree.canLink(grandchild.getId(), a.getId()));
		assertFalse(tree.link(grandchild.getId(), a.getId()));
		assertFalse(tree.link(child.getId(), child.getId()));
		assertFalse(tree.link(a.getId(), "missing"));
		assertTrue(tree.getChildren(grandchild).isEmpty());
	}

	@Test
	public void unlinkKeepsGoalUnderOtherParent()
	{
		Goal rfd = new Goal("Recipe for Disaster");
		tree.add(a.getId(), rfd);
		tree.link(b.getId(), rfd.getId());

		assertTrue(tree.unlink(a.getId(), rfd.getId()));

		assertEquals(List.of(b), tree.getParents(rfd.getId()));
		assertEquals(List.of("A", "B", "C"), titles(tree.getRoots()));
	}

	@Test
	public void unlinkLastParentMakesGoalRoot()
	{
		Goal child = new Goal("A1");
		tree.add(a.getId(), child);

		assertTrue(tree.unlink(a.getId(), child.getId()));

		assertEquals(List.of("A", "B", "C", "A1"), titles(tree.getRoots()));
		assertEquals(child, tree.find(child.getId()));
		assertFalse(tree.unlink(a.getId(), child.getId()));
	}

	@Test
	public void removeKeepsSharedChildrenAndDropsOwnedOnes()
	{
		Goal shared = new Goal("Shared");
		Goal owned = new Goal("Owned");
		Goal ownedGrandchild = new Goal("Owned child");
		tree.add(a.getId(), shared);
		tree.add(a.getId(), owned);
		tree.add(owned.getId(), ownedGrandchild);
		tree.link(b.getId(), shared.getId());

		assertTrue(tree.remove(a.getId()));

		assertNull(tree.find(a.getId()));
		assertNull(tree.find(owned.getId()));
		assertNull(tree.find(ownedGrandchild.getId()));
		assertEquals(shared, tree.find(shared.getId()));
		assertEquals(List.of(b), tree.getParents(shared.getId()));
		assertEquals(List.of("B", "C"), titles(tree.getRoots()));
	}

	@Test
	public void removeSharedGoalRemovesItFromAllParents()
	{
		Goal shared = new Goal("Shared");
		tree.add(a.getId(), shared);
		tree.link(b.getId(), shared.getId());

		assertTrue(tree.remove(shared.getId()));

		assertTrue(tree.getChildren(a).isEmpty());
		assertTrue(tree.getChildren(b).isEmpty());
		assertEquals(3, tree.size());
	}

	@Test
	public void moveOnlyAffectsTheGivenParent()
	{
		Goal x = new Goal("X");
		Goal y = new Goal("Y");
		tree.add(a.getId(), x);
		tree.add(a.getId(), y);
		tree.link(b.getId(), y.getId());
		tree.link(b.getId(), x.getId());

		assertTrue(tree.moveUp(a.getId(), y.getId()));

		assertEquals(List.of("Y", "X"), titles(tree.getChildren(a)));
		assertEquals(List.of("Y", "X"), titles(tree.getChildren(b)));
		assertTrue(tree.moveUp(b.getId(), x.getId()));
		assertEquals(List.of("Y", "X"), titles(tree.getChildren(a)));
		assertEquals(List.of("X", "Y"), titles(tree.getChildren(b)));
	}

	@Test
	public void outdentSharedGoalKeepsOtherParent()
	{
		Goal shared = new Goal("Shared");
		tree.add(a.getId(), shared);
		tree.link(b.getId(), shared.getId());

		assertTrue(tree.outdent(null, a.getId(), shared.getId()));

		assertTrue(tree.getChildren(a).isEmpty());
		assertEquals(List.of(b), tree.getParents(shared.getId()));
		// Under en annan förälder blir det inte även rot.
		assertEquals(List.of("A", "Shared", "B", "C"), titles(tree.getRoots()));
	}

	@Test
	public void indentRefusesToPutGoalUnderItsOwnDescendant()
	{
		// Under A ligger X och Y, och X är även delmål till Y.
		Goal x = new Goal("X");
		Goal y = new Goal("Y");
		tree.add(a.getId(), x);
		tree.add(a.getId(), y);
		assertTrue(tree.link(y.getId(), x.getId()));

		// Indrag skulle lägga Y under X, men Y är förfader till X.
		assertFalse(tree.canIndent(a.getId(), y.getId()));
		assertFalse(tree.indent(a.getId(), y.getId()));
	}

	@Test
	public void forEachVisitsSharedGoalOnce()
	{
		Goal shared = new Goal("Shared");
		tree.add(a.getId(), shared);
		tree.link(b.getId(), shared.getId());
		tree.add(shared.getId(), new Goal("Deep"));

		List<String> visited = new ArrayList<>();
		tree.forEach(goal -> visited.add(goal.getTitle()));

		assertEquals(List.of("A", "Shared", "Deep", "B", "C"), visited);
		assertEquals(visited.size(), tree.flatten().size());
	}

	@Test
	public void loadRepairsBrokenData()
	{
		Goal x = new Goal("X");
		Goal y = new Goal("Y");
		Goal orphan = new Goal("Orphan");
		x.getChildIds().addAll(List.of(y.getId(), "missing", y.getId()));
		// Cykel X -> Y -> X.
		y.getChildIds().add(x.getId());

		GoalTree loaded = GoalTree.load(List.of(x.getId(), x.getId(), "missing"), List.of(x, y, orphan, x));

		assertEquals(List.of("X", "Orphan"), titles(loaded.getRoots()));
		assertEquals(List.of(y.getId()), x.getChildIds());
		assertTrue(y.getChildIds().isEmpty());
		assertEquals(3, loaded.size());
	}

	private static List<String> titles(List<Goal> goals)
	{
		List<String> result = new ArrayList<>();
		goals.forEach(goal -> result.add(goal.getTitle()));
		return result;
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;
import org.junit.Test;

public class ItemRequirementTest
{
	@Test
	public void countsAgainstQuantity()
	{
		ItemRequirement requirement = new ItemRequirement(ItemID.SHARK, "Shark", 100, false);

		GoalProgress partial = requirement.progress(items(ItemID.SHARK, 37));
		assertFalse(partial.isComplete());
		assertEquals("37/100", partial.getLabel());

		assertTrue(requirement.progress(items(ItemID.SHARK, 100)).isComplete());
	}

	@Test
	public void missingItemCountsAsZero()
	{
		GoalProgress progress = new ItemRequirement(ItemID.SHARK, "Shark", 1, false).progress(items(ItemID.COINS, 5));
		assertEquals(0, progress.getCurrent());
		assertFalse(progress.isComplete());
	}

	@Test
	public void unknownItemDataGivesNoProgress()
	{
		assertNull(new ItemRequirement(ItemID.SHARK, "Shark", 1, false).progress(GameData.EMPTY));
	}

	@Test
	public void variantsAreCountedOnlyWhenEnabled()
	{
		// Hitta ett föremål som faktiskt har varianter i klientens tabell.
		int base = ItemVariationMapping.map(ItemID.AMULET_OF_GLORY_6);
		int variant = ItemVariationMapping.getVariations(base).stream()
			.filter(id -> id != ItemID.AMULET_OF_GLORY_6)
			.findFirst()
			.orElseThrow(AssertionError::new);

		GameData data = items(variant, 1);
		assertFalse(new ItemRequirement(ItemID.AMULET_OF_GLORY_6, "Glory", 1, false).progress(data).isComplete());
		assertTrue(new ItemRequirement(ItemID.AMULET_OF_GLORY_6, "Glory", 1, true).progress(data).isComplete());
	}

	@Test
	public void describeIncludesQuantityAboveOne()
	{
		assertEquals("Fire cape", new ItemRequirement(ItemID.TZHAAR_CAPE_FIRE, "Fire cape", 1, false).describe());
		assertEquals("1,000 x Shark", new ItemRequirement(ItemID.SHARK, "Shark", 1000, false).describe());
	}

	@Test(expected = IllegalArgumentException.class)
	public void zeroQuantityIsRejected()
	{
		new ItemRequirement(ItemID.SHARK, "Shark", 0, false);
	}

	private static GameData items(int itemId, long count)
	{
		Map<Integer, Long> map = new HashMap<>();
		map.put(itemId, count);
		return new GameData()
		{
			@Override
			public long getXp(net.runelite.api.Skill skill)
			{
				return -1;
			}

			@Override
			public long getItemCount(int id)
			{
				return map.getOrDefault(id, 0L);
			}
		};
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class NextGoalsTest
{
	@Test
	public void childrenComeBeforeTheirParent()
	{
		GoalTree tree = new GoalTree();
		Goal fireCape = new Goal("Fire cape");
		tree.add(null, fireCape);
		tree.add(fireCape.getId(), new Goal("70 Ranged"));
		tree.add(fireCape.getId(), new Goal("43 Prayer"));
		tree.add(null, new Goal("Barrows gloves"));

		assertEquals(List.of("70 Ranged", "43 Prayer", "Barrows gloves"), titles(NextGoals.select(tree, id -> null, 5)));
	}

	@Test
	public void parentAppearsWhenAllChildrenAreDone()
	{
		GoalTree tree = new GoalTree();
		Goal parent = new Goal("Fire cape");
		Goal child = new Goal("70 Ranged");
		child.markCompleted(true, 1L);
		tree.add(null, parent);
		tree.add(parent.getId(), child);

		assertEquals(List.of("Fire cape"), titles(NextGoals.select(tree, id -> null, 5)));
	}

	@Test
	public void completedGoalsAndTheirSubtreesAreSkipped()
	{
		GoalTree tree = new GoalTree();
		Goal done = new Goal("Done");
		done.markCompleted(true, 1L);
		tree.add(null, done);
		tree.add(done.getId(), new Goal("Leftover child"));
		tree.add(null, new Goal("Next"));

		assertEquals(List.of("Next"), titles(NextGoals.select(tree, id -> null, 5)));
	}

	@Test
	public void limitIsRespectedAndProgressIsIncluded()
	{
		GoalTree tree = new GoalTree();
		Goal first = new Goal("First");
		tree.add(null, first);
		tree.add(null, new Goal("Second"));
		tree.add(null, new Goal("Third"));
		Map<String, GoalProgress> progress = Map.of(first.getId(), new GoalProgress(1, 4, false, "1/4"));

		List<NextGoals.Entry> entries = NextGoals.select(tree, progress::get, 2);

		assertEquals(List.of("First", "Second"), titles(entries));
		assertEquals("1/4", entries.get(0).getProgressLabel());
		assertEquals(0.25, entries.get(0).getFraction(), 0.0);
		assertNull(entries.get(1).getProgressLabel());
	}

	private static List<String> titles(List<NextGoals.Entry> entries)
	{
		List<String> titles = new ArrayList<>();
		entries.forEach(entry -> titles.add(entry.getTitle()));
		return titles;
	}

	@Test
	public void sharedGoalIsSuggestedOnce()
	{
		GoalTree tree = new GoalTree();
		Goal gloves = new Goal("Barrows gloves");
		Goal questCape = new Goal("Quest cape");
		Goal rfd = new Goal("Recipe for Disaster");
		tree.add(null, gloves);
		tree.add(null, questCape);
		tree.add(gloves.getId(), rfd);
		tree.link(questCape.getId(), rfd.getId());
		tree.add(questCape.getId(), new Goal("Dragon Slayer II"));

		assertEquals(List.of("Recipe for Disaster", "Dragon Slayer II"), titles(NextGoals.select(tree, id -> null, 5)));
	}

	@Test
	public void aggregateIsNeverSuggestedItself()
	{
		GoalTree tree = new GoalTree();
		Goal cape = new Goal("Quest cape");
		cape.setAggregate(true);
		Goal done = new Goal("Cook's Assistant");
		done.markCompleted(true, 1L);
		tree.add(null, cape);
		tree.add(cape.getId(), done);
		tree.add(cape.getId(), new Goal("Dragon Slayer II"));
		tree.add(null, new Goal("Fire cape"));

		assertEquals(List.of("Dragon Slayer II", "Fire cape"), titles(NextGoals.select(tree, id -> null, 5)));

		// Med alla delmål klara men utan att vara klart självt (t.ex. eget krav) föreslås det ändå inte.
		tree.getChildren(cape).forEach(goal -> goal.markCompleted(true, 1L));
		assertEquals(List.of("Fire cape"), titles(NextGoals.select(tree, id -> null, 5)));
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

public class SkillRequirementTest
{
	@Test
	public void levelGoalIsCompleteExactlyAtLevelXp()
	{
		SkillRequirement requirement = SkillRequirement.level(Skill.AGILITY, 70);
		int xpFor70 = Experience.getXpForLevel(70);

		GoalProgress below = requirement.progress(xp(Skill.AGILITY, xpFor70 - 1));
		assertFalse(below.isComplete());
		assertEquals("69/70", below.getLabel());

		GoalProgress at = requirement.progress(xp(Skill.AGILITY, xpFor70));
		assertTrue(at.isComplete());
		assertEquals("70/70", at.getLabel());
		assertEquals(1.0, at.fraction(), 0.0);
	}

	@Test
	public void virtualLevelsUseXpBeyond99()
	{
		SkillRequirement requirement = SkillRequirement.level(Skill.FISHING, 105);

		assertFalse(requirement.progress(xp(Skill.FISHING, Experience.getXpForLevel(99))).isComplete());
		assertTrue(requirement.progress(xp(Skill.FISHING, Experience.getXpForLevel(105))).isComplete());
	}

	@Test
	public void xpGoalComparesRawXp()
	{
		SkillRequirement requirement = SkillRequirement.xp(Skill.MINING, 1_000_000);

		GoalProgress half = requirement.progress(xp(Skill.MINING, 500_000));
		assertFalse(half.isComplete());
		assertEquals(0.5, half.fraction(), 0.0001);
		assertEquals("500K/1M", half.getLabel());

		assertTrue(requirement.progress(xp(Skill.MINING, 1_000_000)).isComplete());
	}

	@Test
	public void unknownXpGivesNoProgress()
	{
		assertNull(SkillRequirement.level(Skill.SLAYER, 50).progress(GameData.EMPTY));
	}

	@Test
	public void describeGivesReadableTitle()
	{
		assertEquals("70 Agility", SkillRequirement.level(Skill.AGILITY, 70).describe());
		assertEquals("13,034,431 Agility XP", SkillRequirement.xp(Skill.AGILITY, 13_034_431).describe());
	}

	@Test(expected = IllegalArgumentException.class)
	public void levelAboveVirtualMaxIsRejected()
	{
		SkillRequirement.level(Skill.AGILITY, 127);
	}

	@Test(expected = IllegalArgumentException.class)
	public void xpAboveMaxIsRejected()
	{
		SkillRequirement.xp(Skill.AGILITY, 200_000_001L);
	}

	@Test
	public void xpGainCountsOnlyXpAfterStart()
	{
		SkillRequirement requirement = SkillRequirement.xpGain(Skill.MINING, 1_000_000, 500_000);

		GoalProgress halfway = requirement.progress(xp(Skill.MINING, 1_250_000));
		assertEquals(250_000, halfway.getCurrent());
		assertEquals(500_000, halfway.getTarget());
		assertEquals("250K/500K gained", halfway.getLabel());
		assertFalse(halfway.isComplete());

		assertTrue(requirement.progress(xp(Skill.MINING, 1_500_000)).isComplete());
		assertEquals(1_500_000, requirement.targetXp());
	}

	@Test
	public void xpGainNeverShowsNegativeProgress()
	{
		// T.ex. om startpunkten sattes på ett annat konto med mer XP.
		GoalProgress progress = SkillRequirement.xpGain(Skill.MINING, 1_000_000, 500_000)
			.progress(xp(Skill.MINING, 900_000));

		assertEquals(0, progress.getCurrent());
	}

	@Test(expected = IllegalArgumentException.class)
	public void xpGainPastMaxXpIsRejected()
	{
		SkillRequirement.xpGain(Skill.MINING, 199_999_999L, 2);
	}

	@Test
	public void sameGainFromDifferentStartIsNotEqual()
	{
		assertFalse(SkillRequirement.xpGain(Skill.MINING, 0, 500).equals(SkillRequirement.xpGain(Skill.MINING, 10, 500)));
		assertFalse(SkillRequirement.xpGain(Skill.MINING, 0, 500).equals(SkillRequirement.xp(Skill.MINING, 500)));
	}

	@Test
	public void describeProgressShowsExactNumbers()
	{
		SkillRequirement level = SkillRequirement.level(Skill.AGILITY, 70);
		assertEquals("Level 60 / 70\n273,742 / 737,627 XP\n463,885 XP left",
			level.describeProgress(level.progress(xp(Skill.AGILITY, 273_742))));

		SkillRequirement total = SkillRequirement.xp(Skill.AGILITY, 13_034_431);
		assertEquals("1,000,000 / 13,034,431 XP\n12,034,431 XP left",
			total.describeProgress(total.progress(xp(Skill.AGILITY, 1_000_000))));

		SkillRequirement gain = SkillRequirement.xpGain(Skill.MINING, 1_000_000, 500_000);
		assertEquals("Gained 250,000 / 500,000 XP\n250,000 XP left\nStarted at 1,000,000 XP, done at 1,500,000 XP",
			gain.describeProgress(gain.progress(xp(Skill.MINING, 1_250_000))));
	}

	static GameData xp(Skill skill, long xp)
	{
		Map<Skill, Long> map = new EnumMap<>(Skill.class);
		map.put(skill, xp);
		return s -> map.getOrDefault(s, -1L);
	}
}

package com.gielinorgoals.persistence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import java.util.Map;
import org.junit.Test;

public class ContainerCacheTest
{
	private final Gson gson = new Gson();

	@Test
	public void roundTripKeepsItemsAndTimestamp()
	{
		ContainerCache cache = new ContainerCache(1234L, Map.of(995, 1_000_000L, 385, 250L));

		ContainerCache loaded = ContainerCache.fromJson(gson, cache.toJson(gson));

		assertEquals(1234L, loaded.getSavedAt());
		assertEquals(Long.valueOf(1_000_000L), loaded.getItems().get(995));
		assertEquals(Long.valueOf(250L), loaded.getItems().get(385));
	}

	@Test
	public void missingOrBrokenDataGivesNull()
	{
		assertNull(ContainerCache.fromJson(gson, null));
		assertNull(ContainerCache.fromJson(gson, ""));
		assertNull(ContainerCache.fromJson(gson, "{broken"));
		assertNull(ContainerCache.fromJson(gson, "{\"savedAt\":1}"));
		assertNull(ContainerCache.fromJson(gson, "{\"savedAt\":1,\"items\":{\"x\":1}}"));
	}
}

package com.gielinorgoals.persistence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.GoalTree;
import com.gielinorgoals.model.CombatAchievementRequirement;
import com.gielinorgoals.model.DiaryArea;
import com.gielinorgoals.model.DiaryRequirement;
import com.gielinorgoals.model.DiaryTier;
import com.gielinorgoals.model.ItemRequirement;
import com.gielinorgoals.model.QuestRequirement;
import com.gielinorgoals.model.Requirement;
import com.gielinorgoals.model.SkillRequirement;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.List;
import org.junit.Test;

public class GoalSerializerTest
{
	private final GoalSerializer serializer = new GoalSerializer(new Gson(), new SchemaMigrator());

	@Test
	public void roundTripKeepsTreeAndFields()
	{
		Goal parent = new Goal("Get Fire cape");
		parent.setNote("Bring stamina potions");
		parent.markCompleted(true, 42L);
		parent.setExpanded(false);
		Goal child = new Goal("Ranged level 75");
		GoalTree tree = treeOf(parent);
		tree.add(parent.getId(), child);
		parent.setExpanded(false);

		String json = serializer.serialize(tree);
		LoadResult result = serializer.deserialize(json);

		assertEquals(LoadResult.Status.OK, result.getStatus());
		assertFalse(result.isMigrated());
		assertEquals(1, result.getGoals().size());

		Goal loaded = result.getGoals().get(0);
		assertEquals(parent.getId(), loaded.getId());
		assertEquals("Get Fire cape", loaded.getTitle());
		assertEquals("Bring stamina potions", loaded.getNote());
		assertTrue(loaded.isCompleted());
		assertEquals(Long.valueOf(42L), loaded.getCompletedAt());
		assertFalse(loaded.isExpanded());
		assertEquals(List.of(child.getId()), loaded.getChildIds());
		assertEquals("Ranged level 75", result.getTree().find(child.getId()).getTitle());
	}

	private static GoalTree treeOf(Goal... roots)
	{
		GoalTree tree = new GoalTree();
		for (Goal root : roots)
		{
			tree.add(null, root);
		}
		return tree;
	}

	@Test
	public void serializedJsonContainsSchemaVersion()
	{
		JsonObject root = new Gson().fromJson(serializer.serialize(new GoalTree()), JsonObject.class);
		assertEquals(SchemaMigrator.CURRENT_VERSION, root.get("schemaVersion").getAsInt());
	}

	@Test
	public void missingDataGivesEmptyList()
	{
		assertTrue(serializer.deserialize(null).getGoals().isEmpty());
		assertEquals(LoadResult.Status.OK, serializer.deserialize("  ").getStatus());
	}

	@Test
	public void invalidJsonIsReportedAsCorrupt()
	{
		assertEquals(LoadResult.Status.CORRUPT, serializer.deserialize("{not json").getStatus());
		assertEquals(LoadResult.Status.CORRUPT, serializer.deserialize("[1,2,3]").getStatus());
		assertEquals(LoadResult.Status.CORRUPT, serializer.deserialize("{\"schemaVersion\":1,\"goals\":5}").getStatus());
		assertEquals(LoadResult.Status.CORRUPT, serializer.deserialize("{\"schemaVersion\":\"x\"}").getStatus());
	}

	@Test
	public void newerVersionIsReadOnly()
	{
		String json = "{\"schemaVersion\":99,\"goals\":[{\"id\":\"a\",\"title\":\"Future\"}]}";
		LoadResult result = serializer.deserialize(json);

		assertEquals(LoadResult.Status.NEWER_VERSION, result.getStatus());
		assertTrue(result.isReadOnly());
		assertEquals("Future", result.getGoals().get(0).getTitle());
	}

	@Test
	public void skillRequirementRoundTrips()
	{
		Goal level = new Goal("");
		level.setRequirement(SkillRequirement.level(Skill.AGILITY, 70));
		Goal xp = new Goal("Max fishing xp");
		xp.setRequirement(SkillRequirement.xp(Skill.FISHING, 200_000_000L));

		List<Goal> loaded = serializer.deserialize(serializer.serialize(treeOf(level, xp))).getGoals();

		assertEquals(SkillRequirement.level(Skill.AGILITY, 70), loaded.get(0).getRequirement());
		assertEquals("70 Agility", loaded.get(0).getDisplayTitle());
		assertEquals(SkillRequirement.xp(Skill.FISHING, 200_000_000L), loaded.get(1).getRequirement());
		assertEquals("Max fishing xp", loaded.get(1).getDisplayTitle());
	}

	@Test
	public void xpGainRequirementKeepsStartXp()
	{
		Goal goal = new Goal("");
		goal.setRequirement(SkillRequirement.xpGain(Skill.MINING, 1_234_567L, 500_000L));

		List<Goal> loaded = serializer.deserialize(serializer.serialize(treeOf(goal))).getGoals();

		SkillRequirement requirement = (SkillRequirement) loaded.get(0).getRequirement();
		assertEquals(SkillRequirement.Mode.XP_GAIN, requirement.getMode());
		assertEquals(1_234_567L, requirement.getStartXp());
		assertEquals(500_000L, requirement.getTarget());
		assertEquals("Gain 500,000 Mining XP", loaded.get(0).getDisplayTitle());
	}

	@Test
	public void version5LoadsIntoVersion6WithoutDataLoss()
	{
		String json = "{\"schemaVersion\":5,\"goals\":[{\"id\":\"a\",\"title\":\"Barrows gloves\",\"note\":\"RFD\","
			+ "\"completed\":true,\"completedAt\":1700000000000,\"expanded\":false,\"children\":["
			+ "{\"id\":\"b\",\"title\":\"\",\"completed\":false,\"expanded\":true,\"children\":[],"
			+ "\"requirement\":{\"type\":\"SKILL\",\"skill\":\"COOKING\",\"mode\":\"LEVEL\",\"target\":70}}]}]}";

		LoadResult result = serializer.deserialize(json);

		assertEquals(LoadResult.Status.OK, result.getStatus());
		assertTrue(result.isMigrated());
		Goal parent = result.getGoals().get(0);
		assertEquals("Barrows gloves", parent.getTitle());
		assertEquals("RFD", parent.getNote());
		assertTrue(parent.isCompleted());
		assertEquals(Long.valueOf(1_700_000_000_000L), parent.getCompletedAt());
		assertFalse(parent.isExpanded());
		// Nya fält: inget datum hittas på för gamla mål.
		assertNull(parent.getCreatedAt());
		assertFalse(parent.isCompletedAtApprox());
		Goal child = result.getTree().getChildren(parent).get(0);
		assertEquals(SkillRequirement.level(Skill.COOKING, 70), child.getRequirement());
		assertNull(child.getCreatedAt());

		JsonObject saved = new Gson().fromJson(serializer.serialize(result.getTree()), JsonObject.class);
		assertEquals(SchemaMigrator.CURRENT_VERSION, saved.get("schemaVersion").getAsInt());
	}

	@Test
	public void xpGainPastMaxXpIsDroppedAsInvalid()
	{
		String json = "{\"schemaVersion\":5,\"goals\":[{\"id\":\"a\",\"title\":\"x\",\"requirement\":"
			+ "{\"type\":\"SKILL\",\"skill\":\"MINING\",\"mode\":\"XP_GAIN\",\"target\":2,\"startXp\":200000000}}]}";

		assertEquals(null, serializer.deserialize(json).getGoals().get(0).getRequirement());
	}

	@Test
	public void itemRequirementRoundTrips()
	{
		Goal goal = new Goal("");
		ItemRequirement requirement = new ItemRequirement(ItemID.TZHAAR_CAPE_FIRE, "Fire cape", 1, true);
		goal.setRequirement(requirement);

		String json = serializer.serialize(treeOf(goal));
		Goal loaded = serializer.deserialize(json).getGoals().get(0);

		assertTrue(json.contains("\"type\":\"ITEM\""));
		assertEquals(requirement, loaded.getRequirement());
		assertEquals("Fire cape", loaded.getDisplayTitle());
	}

	@Test
	public void achievementRequirementsRoundTrip()
	{
		List<Requirement> requirements = List.of(
			new QuestRequirement(42, "Dragon Slayer I"),
			new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.ELITE),
			new CombatAchievementRequirement(17, "Noxious Foe", "Easy"));
		List<Goal> goals = new java.util.ArrayList<>();
		for (Requirement requirement : requirements)
		{
			Goal goal = new Goal("");
			goal.setRequirement(requirement);
			goals.add(goal);
		}

		List<Goal> loaded = serializer.deserialize(serializer.serialize(treeOf(goals.toArray(new Goal[0])))).getGoals();

		for (int i = 0; i < requirements.size(); i++)
		{
			assertEquals(requirements.get(i), loaded.get(i).getRequirement());
		}
	}

	@Test
	public void serializedRequirementHasTypeField()
	{
		Goal goal = new Goal("x");
		goal.setRequirement(SkillRequirement.level(Skill.MINING, 60));
		String json = serializer.serialize(treeOf(goal));

		assertTrue(json.contains("\"type\":\"SKILL\""));
		assertTrue(json.contains("\"skill\":\"MINING\""));
	}

	@Test
	public void unknownOrInvalidRequirementBecomesManualGoal()
	{
		String json = "{\"schemaVersion\":2,\"goals\":["
			+ "{\"id\":\"a\",\"title\":\"A\",\"requirement\":{\"type\":\"TELEPORT\"}},"
			+ "{\"id\":\"b\",\"title\":\"B\",\"requirement\":{\"type\":\"SKILL\",\"skill\":\"NOPE\",\"mode\":\"LEVEL\",\"target\":50}},"
			+ "{\"id\":\"c\",\"title\":\"C\",\"requirement\":{\"type\":\"SKILL\",\"skill\":\"MINING\",\"mode\":\"LEVEL\",\"target\":500}}"
			+ "]}";
		LoadResult result = serializer.deserialize(json);

		assertEquals(LoadResult.Status.OK, result.getStatus());
		assertEquals(3, result.getGoals().size());
		result.getGoals().forEach(goal -> assertNull(goal.getRequirement()));
	}

	@Test
	public void version1DataIsMigrated()
	{
		LoadResult result = serializer.deserialize("{\"schemaVersion\":1,\"goals\":[{\"id\":\"a\",\"title\":\"Old\"}]}");

		assertEquals(LoadResult.Status.OK, result.getStatus());
		assertTrue(result.isMigrated());
		assertEquals("Old", result.getGoals().get(0).getTitle());
	}

	@Test
	public void missingFieldsAreFilledIn()
	{
		String json = "{\"schemaVersion\":1,\"goals\":[{\"title\":\"No id\"},null,{\"id\":\"b\"}]}";
		List<Goal> goals = serializer.deserialize(json).getGoals();

		assertEquals(2, goals.size());
		assertNotNull(goals.get(0).getId());
		assertNotNull(goals.get(0).getChildIds());
		assertEquals("", goals.get(1).getTitle());
		assertNull(goals.get(1).getCompletedAt());
	}

	@Test
	public void realisticVersion6FileIsFlattenedWithoutDataLoss() throws Exception
	{
		LoadResult result = serializer.deserialize(resource("goals-v6.json"));

		assertEquals(LoadResult.Status.OK, result.getStatus());
		assertTrue(result.isMigrated());
		assertRealisticGoals(result.getTree());

		// Sparat i nya formatet: platt lista, rootIds, inga nästlade children.
		JsonObject saved = new Gson().fromJson(serializer.serialize(result.getTree()), JsonObject.class);
		assertEquals(SchemaMigrator.CURRENT_VERSION, saved.get("schemaVersion").getAsInt());
		assertEquals("[\"gloves\",\"firecape\",\"karamja\",\"noxious\",\"legacy\"]", saved.get("rootIds").toString());
		assertEquals(11, saved.getAsJsonArray("goals").size());
		for (com.google.gson.JsonElement goal : saved.getAsJsonArray("goals"))
		{
			assertFalse(goal.getAsJsonObject().has("children"));
			assertTrue(goal.getAsJsonObject().has("childIds"));
		}

		// Och läses tillbaka likadant utan ny migrering.
		LoadResult reloaded = serializer.deserialize(serializer.serialize(result.getTree()));
		assertFalse(reloaded.isMigrated());
		assertRealisticGoals(reloaded.getTree());
	}

	private static void assertRealisticGoals(GoalTree tree)
	{
		assertEquals(List.of("gloves", "firecape", "karamja", "noxious", "legacy"), tree.getRootIds());
		assertEquals(11, tree.size());

		Goal gloves = tree.find("gloves");
		assertEquals("Barrows gloves", gloves.getTitle());
		assertEquals("Cooking and RFD subquests first", gloves.getNote());
		assertEquals(Long.valueOf(1_762_000_000_000L), gloves.getCreatedAt());
		assertEquals(List.of("rfd", "qp"), gloves.getChildIds());

		Goal rfd = tree.find("rfd");
		assertEquals(new QuestRequirement(159, "Recipe for Disaster"), rfd.getRequirement());
		assertFalse(rfd.isExpanded());
		assertEquals(List.of("cooking", "dt"), rfd.getChildIds());
		assertEquals(List.of(gloves), tree.getParents("rfd"));

		Goal cooking = tree.find("cooking");
		assertEquals(SkillRequirement.level(Skill.COOKING, 70), cooking.getRequirement());
		assertTrue(cooking.isCompleted());
		assertEquals(Long.valueOf(1_763_000_000_000L), cooking.getCompletedAt());
		assertTrue(cooking.isCompletedAtApprox());

		Goal dt = tree.find("dt");
		assertEquals("Desert Treasure I", dt.getTitle());
		assertTrue(dt.isCompleted());
		assertFalse(dt.isCompletedAtApprox());

		Goal qp = tree.find("qp");
		assertNull(qp.getRequirement());
		assertNull(qp.getCreatedAt());

		Goal fireCape = tree.find("firecape");
		assertEquals(new ItemRequirement(ItemID.TZHAAR_CAPE_FIRE, "Fire cape", 1, true), fireCape.getRequirement());
		assertEquals("Bring stamina potions", fireCape.getNote());
		assertFalse(fireCape.isExpanded());
		assertEquals(List.of("ranged"), fireCape.getChildIds());
		assertEquals(SkillRequirement.xpGain(Skill.RANGED, 1_234_567L, 500_000L), tree.find("ranged").getRequirement());

		Goal karamja = tree.find("karamja");
		assertEquals(new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.ELITE), karamja.getRequirement());
		Goal task = tree.find("karamja-task");
		assertTrue(task.isCompleted());
		assertTrue(task.isCompletedAtApprox());

		Goal noxious = tree.find("noxious");
		assertEquals(new CombatAchievementRequirement(17, "Noxious Foe", "Easy"), noxious.getRequirement());
		assertTrue(noxious.isCompleted());
		// Saknade "children" i v6 blir en tom lista.
		assertTrue(noxious.getChildIds().isEmpty());

		Goal legacy = tree.find("legacy");
		assertTrue(legacy.isCompleted());
		assertEquals(Long.valueOf(1_700_000_000_000L), legacy.getCompletedAt());
		assertNull(legacy.getCreatedAt());
		assertFalse(legacy.isCompletedAtApprox());

		// Visningsordningen är densamma som i det gamla trädet.
		List<String> order = new java.util.ArrayList<>();
		tree.forEach(goal -> order.add(goal.getId()));
		assertEquals(List.of("gloves", "rfd", "cooking", "dt", "qp", "firecape", "ranged", "karamja", "karamja-task",
			"noxious", "legacy"), order);
	}

	private static String resource(String name) throws java.io.IOException
	{
		try (java.io.InputStream in = GoalSerializerTest.class.getResourceAsStream(name))
		{
			return new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
		}
	}

	@Test
	public void sharedGoalIsStoredOnceAndKeepsBothParents()
	{
		Goal gloves = new Goal("Barrows gloves");
		Goal questCape = new Goal("Quest cape");
		Goal rfd = new Goal("Recipe for Disaster");
		GoalTree tree = treeOf(gloves, questCape);
		tree.add(gloves.getId(), rfd);
		tree.link(questCape.getId(), rfd.getId());

		String json = serializer.serialize(tree);
		GoalTree loaded = serializer.deserialize(json).getTree();

		assertEquals(3, new Gson().fromJson(json, JsonObject.class).getAsJsonArray("goals").size());
		assertEquals(2, loaded.getParents(rfd.getId()).size());
		assertEquals(List.of(gloves.getId(), questCape.getId()), loaded.getRootIds());
	}
}

package com.gielinorgoals.persistence;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Map;
import java.util.function.UnaryOperator;
import org.junit.Test;

public class SchemaMigratorTest
{
	@Test
	public void currentVersionIsUntouched()
	{
		String json = "{\"schemaVersion\":" + SchemaMigrator.CURRENT_VERSION + ",\"goals\":[]}";
		JsonObject result = new SchemaMigrator().migrate(parse(json));

		assertEquals(SchemaMigrator.CURRENT_VERSION, SchemaMigrator.versionOf(result));
		assertEquals(0, result.getAsJsonArray("goals").size());
	}

	@Test
	public void version1IsMigratedToCurrentWithGoalsIntact()
	{
		JsonObject result = new SchemaMigrator().migrate(parse("{\"schemaVersion\":1,\"goals\":[{\"id\":\"a\"}]}"));

		assertEquals(SchemaMigrator.CURRENT_VERSION, SchemaMigrator.versionOf(result));
		assertEquals(1, result.getAsJsonArray("goals").size());
	}

	@Test
	public void stepsRunInOrderAndBumpVersion()
	{
		UnaryOperator<JsonObject> v1ToV2 = root ->
		{
			root.addProperty("trail", "a");
			return root;
		};
		UnaryOperator<JsonObject> v2ToV3 = root ->
		{
			root.addProperty("trail", root.get("trail").getAsString() + "b");
			return root;
		};
		SchemaMigrator migrator = new SchemaMigrator(Map.of(1, v1ToV2, 2, v2ToV3));

		JsonObject result = migrator.migrate(parse("{\"schemaVersion\":1}"), 3);

		assertEquals(3, SchemaMigrator.versionOf(result));
		assertEquals("ab", result.get("trail").getAsString());
	}

	@Test(expected = IllegalStateException.class)
	public void missingStepThrows()
	{
		new SchemaMigrator().migrate(parse("{}"), 1);
	}

	private static JsonObject parse(String json)
	{
		return new Gson().fromJson(json, JsonObject.class);
	}
}

